# semantic-mutant: SM-2093BBD0
from __future__ import annotations

import json
from typing import Any

import pytest

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import ScriptedHTTPServer, ScriptedResponse
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import prepare_fault_case

pytestmark = pytest.mark.verification_kind("unit")


def _collect_refs(node: Any) -> list[str]:
    refs: list[str] = []
    if isinstance(node, dict):
        for key, value in node.items():
            if key == "$ref" and isinstance(value, str):
                refs.append(value)
            else:
                refs.extend(_collect_refs(value))
    elif isinstance(node, list):
        for item in node:
            refs.extend(_collect_refs(item))
    return refs


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_provider_schema_transform_keeps_defs_for_recursive_refs() -> None:
    path = openai_chat_path()
    node = {
        "type": "object",
        "properties": {
            "name": {"type": "string", "minLength": 1},
            "children": {
                "type": "array",
                "items": {"$ref": "#/$defs/Node"},
            },
        },
        "required": ["name"],
    }
    schema = {
        "title": "category_tree",
        "type": "object",
        "properties": {
            "name": {"type": "string", "minLength": 1},
            "children": {
                "type": "array",
                "items": {"$ref": "#/$defs/Node"},
            },
        },
        "required": ["name"],
        "$defs": {"Node": node},
    }
    output = {"name": "root", "children": [{"name": "leaf", "children": []}]}
    with ScriptedHTTPServer(
        port=0,
        routes={
            ("POST", path): [
                ScriptedResponse(
                    status_code=200,
                    headers={"Content-Type": "application/json"},
                    body=openai_success_response(text=json.dumps(output)),
                )
            ]
        },
    ) as server:
        prepare_fault_case(case="aistudio_video", server_base_url=server.base_url)
        router = LLMRouter(
            RouterProfile(model=Model.GEMINI_FLASH, provider=Provider.AISTUDIO)
        )

        response = router.query("Build the category tree.", response_schema=schema)

        body = json.loads(server.recorded_requests("POST", path)[0].body)

    sent = body["response_format"]["json_schema"]["schema"]
    defs = sent.get("$defs", {})
    for ref in _collect_refs(sent):
        assert ref.startswith("#/$defs/")
        assert ref.removeprefix("#/$defs/") in defs
    # A recursive schema cannot be fully inlined, so its definitions must remain.
    assert "$defs" in sent
    assert "Node" in sent["$defs"]
    assert json.loads(response.output_text) == output
